[[nodiscard]] constexpr bool same_frame_flags(
    const openswd3::battle::LegacyBattleActorCoordinateFlags& lhs,
    const openswd3::battle::LegacyBattleActorCoordinateFlags& rhs
) noexcept {
    return lhs.carry == rhs.carry && lhs.parity == rhs.parity &&
        lhs.auxiliary_carry == rhs.auxiliary_carry &&
        lhs.auxiliary_carry_defined == rhs.auxiliary_carry_defined &&
        lhs.zero == rhs.zero && lhs.sign == rhs.sign &&
        lhs.overflow == rhs.overflow &&
        lhs.overflow_defined == rhs.overflow_defined;
}

// An audio CALL commits its return-slot PUSH and twenty wrapper accesses.
// A known-zero arg_0 read and aliased arg_4 write precede sub_486490's
// saved registers and its first unbacked audio-table read.
[[nodiscard]] bool matches_audio_deep_read_stop(
    const openswd3::battle::LegacyBattleActorFrameEntryResult& stopped,
    const openswd3::battle::LegacyBattleActorFrameEntryResult& before_call
) noexcept {
    const bool before_arg_read = stopped.eip == 0x00485D0EU;
    const bool before_arg_write = stopped.eip == 0x00485D14U;
    const bool before_table_read = stopped.eip == 0x0048649FU;
    const u32 id = before_call.last_pushed_value & 0xFFFFU;
    const auto expected_flags = before_arg_read
        ? openswd3::battle::
              LegacyBattleActorCoordinateFlags{.parity = (std::popcount(static_cast<u8>(id)) & 1) == 0, .auxiliary_carry_defined = false}
        : before_arg_write
        ? openswd3::battle::
              LegacyBattleActorCoordinateFlags{.parity = true, .auxiliary_carry_defined = false, .zero = true}
        : openswd3::battle::LegacyBattleActorCoordinateFlags{
              .parity = (std::popcount(static_cast<u8>(id << 4U)) & 1) == 0,
              .auxiliary_carry_defined = false,
              .overflow_defined = false
          };
    return (before_arg_read || before_arg_write || before_table_read) &&
        stopped.stopped_instruction == stopped.eip &&
        stopped.stopped_access_kind ==
        (before_arg_read ? LegacyBattleActorFrameEntryAccessKind::stack_read
             : before_arg_write
             ? LegacyBattleActorFrameEntryAccessKind::stack_write
             : LegacyBattleActorFrameEntryAccessKind::global_read) &&
        stopped.esp == before_call.esp - (before_table_read ? 76U : 48U) &&
        stopped.stopped_token ==
        (before_arg_read        ? stopped.esp + 0x14U
             : before_arg_write ? stopped.esp + 0x18U
                                : 0x004C8ACCU) &&
        stopped.accesses_completed ==
        before_call.accesses_completed +
            (before_arg_read        ? 21U
                 : before_arg_write ? 22U
                                    : 29U) &&
        stopped.last_pushed_value == (before_table_read ? 0U : 0x00485CFAU) &&
        stopped.eax == 1U && stopped.ecx == 0x004C8450U &&
        stopped.ebx == before_call.ebx && stopped.ebp == 0x004C8450U &&
        stopped.esi ==
        (before_arg_read        ? before_call.esi
             : before_arg_write ? 0U
                                : id << 4U) &&
        stopped.edi == id && id != 0U && stopped.sample_nested_arg4_known &&
        stopped.sample_nested_arg4_on_stack == (before_table_read ? 0U : id) &&
        stopped.flags_known == !before_table_read &&
        same_frame_flags(stopped.flags, expected_flags) &&
        stopped.direction_flag == before_call.direction_flag &&
        !stopped.sample_child.returned;
}

// A draw CALL commits its return slot and sub_4170E0 saves four registers.
// Raw headers commit six callee accesses; marker headers with a nonzero
// palette commit seven. The next physical access reads arg_10 at 0x417107.
[[nodiscard]] bool matches_draw_deep_read_stop(
    const openswd3::battle::LegacyBattleActorFrameEntryResult& stopped,
    const openswd3::battle::LegacyBattleActorFrameEntryResult& before_call,
    const LegacyBattleActorFrameEntryRequest& request
) noexcept {
    const bool marker = request.draw_source_bytes[0U] == 0xFFU &&
        request.draw_source_bytes[1U] == 0xFFU;
    const u32 expected_eax = marker ? *request.draw_palette_token_owner
                                    : *request.draw_source_token_owner;
    return stopped.eip == 0x00417107U &&
        stopped.stopped_instruction == 0x00417107U &&
        stopped.stopped_access_kind ==
        LegacyBattleActorFrameEntryAccessKind::stack_read &&
        stopped.esp == before_call.esp - 20U &&
        stopped.stopped_token == stopped.esp + 0x24U &&
        stopped.accesses_completed ==
        before_call.accesses_completed + (marker ? 8U : 7U) &&
        stopped.last_pushed_value == before_call.edi &&
        stopped.eax == expected_eax && stopped.ecx == before_call.ecx &&
        stopped.edx == before_call.edx && stopped.ebx == before_call.ebx &&
        stopped.ebp == 0U && stopped.esi == before_call.esi &&
        stopped.edi == before_call.edi && stopped.flags_known &&
        same_frame_flags(
               stopped.flags,
               {.parity = !marker ||
                    (std::popcount(static_cast<u8>(expected_eax)) & 1) == 0,
                .auxiliary_carry_defined = marker,
                .zero = !marker || expected_eax == 0U,
                .sign = marker && (expected_eax & 0x80000000U) != 0U}
        ) &&
        stopped.direction_flag == before_call.direction_flag &&
        !stopped.draw_child.returned;
}

// The release wrapper and CRT callee commit ten accesses before the debug
// flag read; the non-debug path reaches its first indirect free-hook read.
[[nodiscard]] bool matches_release_deep_global_stop(
    const openswd3::battle::LegacyBattleActorFrameEntryResult& stopped,
    const openswd3::battle::LegacyBattleActorFrameEntryResult& before_call,
    const u32 argument_token,
    const u32 expected_esi,
    const bool linked_node = false
) noexcept {
    const bool before_debug_read = stopped.eip == 0x004885C7U;
    const bool before_argument_read = stopped.eip == 0x00488603U;
    const bool before_hook_read = stopped.eip == 0x00488620U;
    const auto expected_flags = before_debug_read ? before_call.flags
        : before_argument_read
        ? openswd3::battle::
              LegacyBattleActorCoordinateFlags{.parity = true, .auxiliary_carry_defined = false, .zero = true}
        : openswd3::battle::LegacyBattleActorCoordinateFlags{
              .parity =
                  (std::popcount(static_cast<u8>(argument_token)) & 1) == 0,
              .sign = (argument_token & 0x80000000U) != 0U
          };
    return (before_debug_read || before_argument_read || before_hook_read) &&
        stopped.stopped_instruction == stopped.eip &&
        stopped.stopped_token ==
        (before_debug_read          ? 0x004A82F4U
             : before_argument_read ? stopped.ebp + 8U
                                    : 0x004A8360U) &&
        stopped.stopped_access_kind ==
        (before_argument_read
             ? LegacyBattleActorFrameEntryAccessKind::stack_read
             : LegacyBattleActorFrameEntryAccessKind::global_read) &&
        stopped.esp == before_call.esp - (before_hook_read ? 72U : 44U) &&
        stopped.ebp == before_call.esp - 28U &&
        stopped.accesses_completed ==
        before_call.accesses_completed + (linked_node ? 13U : 12U) +
            (before_debug_read          ? 0U
                 : before_argument_read ? 1U
                                        : 11U) &&
        stopped.last_pushed_value ==
        (before_hook_read ? 3U : before_call.edi) &&
        stopped.eax == (before_argument_read ? 0U : argument_token) &&
        stopped.ebx == before_call.ebx && stopped.ecx == before_call.ecx &&
        stopped.edx == (before_hook_read ? 1U : before_call.edx) &&
        stopped.esi == expected_esi && stopped.edi == before_call.edi &&
        stopped.flags_known ==
        (before_debug_read ? before_call.flags_known : true) &&
        same_frame_flags(stopped.flags, expected_flags) &&
        stopped.direction_flag == before_call.direction_flag &&
        !stopped.release_child.returned;
}

// The host-surface callee saves three registers, reads both metric arguments,
// and pushes both nested arguments before writing its first host field.
[[nodiscard]] bool matches_host_prewrite_stop(
    const openswd3::battle::LegacyBattleActorFrameEntryResult& stopped,
    const openswd3::battle::LegacyBattleActorFrameEntryResult& before_call
) noexcept {
    return stopped.eip == 0x00433F3FU &&
        stopped.stopped_instruction == 0x00433F3FU &&
        stopped.stopped_token == before_call.ecx + 0x0B50U &&
        stopped.stopped_access_kind ==
        LegacyBattleActorFrameEntryAccessKind::global_write &&
        stopped.esp == before_call.esp - 24U &&
        stopped.accesses_completed == before_call.accesses_completed + 8U &&
        stopped.last_pushed_value == before_call.metric_width_on_stack &&
        stopped.eax == before_call.eax &&
        stopped.ebx == before_call.metric_height_on_stack &&
        stopped.ecx == before_call.ecx && stopped.edx == before_call.edx &&
        stopped.ebp == before_call.ebp && stopped.esi == before_call.ecx &&
        stopped.edi == before_call.metric_width_on_stack &&
        stopped.flags_known == before_call.flags_known &&
        same_frame_flags(stopped.flags, before_call.flags) &&
        stopped.direction_flag == before_call.direction_flag &&
        !stopped.rectangle_child.returned;
}

// All three directed RET fixtures enter at ESP=0x0012FF00: the epilogue
// ADD ESP,0x14 starts at 0x0012FEEC and sets PF/AF only.
constexpr openswd3::battle::LegacyBattleActorCoordinateFlags
    kDirectedOuterReturnFlags{.parity = true, .auxiliary_carry = true};

[[nodiscard]] constexpr openswd3::battle::LegacyBattleActorCoordinateFlags
expected_add_esp_cleanup_flags(const u32 before, const u32 bytes) noexcept {
    const u32 after = before + bytes;
    return {
        .carry = after < before,
        .parity = (std::popcount(static_cast<u8>(after)) & 1) == 0,
        .auxiliary_carry = ((before ^ bytes ^ after) & 0x10U) != 0U,
        .zero = after == 0U,
        .sign = (after & 0x80000000U) != 0U,
        .overflow =
            ((~(before ^ bytes) & (before ^ after)) & 0x80000000U) != 0U,
    };
}

[[nodiscard]] constexpr openswd3::battle::LegacyBattleActorCoordinateFlags
expected_sub_esp_flags(const u32 before, const u32 bytes) noexcept {
    const u32 after = before - bytes;
    return {
        .carry = before < bytes,
        .parity = (std::popcount(static_cast<u8>(after)) & 1) == 0,
        .auxiliary_carry = ((before ^ bytes ^ after) & 0x10U) != 0U,
        .zero = after == 0U,
        .sign = (after & 0x80000000U) != 0U,
        .overflow = (((before ^ bytes) & (before ^ after)) & 0x80000000U) != 0U,
    };
}

[[nodiscard]] constexpr openswd3::battle::LegacyBattleActorCoordinateFlags
expected_add_esp_14_flags(const u32 return_slot) noexcept {
    const u32 before = return_slot - 0x14U;
    return {
        .carry = return_slot < before,
        .parity = (std::popcount(static_cast<u8>(return_slot)) & 1) == 0,
        .auxiliary_carry = (before & 0xFU) + 4U > 0xFU,
        .zero = return_slot == 0U,
        .sign = (return_slot & 0x80000000U) != 0U,
        .overflow =
            (before & 0x80000000U) == 0U && (return_slot & 0x80000000U) != 0U,
    };
}

void expect_frame_reset_first_write_fault(
    openswd3::test::Context& test,
    const openswd3::battle::LegacyBattleActorFrameEntryResult& prefix,
    const openswd3::battle::LegacyBattleActorFrameEntryResult& stopped,
    const u32 return_ip
) {
    const auto& child = stopped.reset_child;
    test.expect_true(
        stopped.status ==
                LegacyBattleActorFrameEntryStatus::reset_child_typed_stop &&
            stopped.eip == 0x00478856U &&
            stopped.stopped_instruction == 0x00478856U &&
            stopped.stopped_access_kind ==
                LegacyBattleActorFrameEntryAccessKind::actor_write &&
            stopped.stopped_token == prefix.esi + 0x2A12U &&
            stopped.last_pushed_value == return_ip &&
            stopped.reset_calls == 1U &&
            stopped.accesses_completed == prefix.accesses_completed + 3U &&
            stopped.esp == prefix.esp - 12U &&
            stopped.eax == 0U && stopped.ecx == prefix.esi &&
            stopped.edx == prefix.edx && stopped.ebx == prefix.esi &&
            stopped.ebp == prefix.ebp && stopped.esi == prefix.esi &&
            stopped.edi == prefix.edi && stopped.flags_known &&
            same_frame_flags(
                stopped.flags,
                openswd3::battle::LegacyBattleActorCoordinateFlags{
                    .parity = true,
                    .auxiliary_carry_defined = false,
                    .zero = true,
                }
            ) &&
            stopped.direction_flag == prefix.direction_flag &&
            child.status == openswd3::battle::
                    LegacyBattleActorRuntimeResetStatus::actor_write_typed_stop &&
            child.accesses_completed == 2U &&
            child.return_eip == 0x00478856U &&
            child.return_esp == prefix.esp - 12U &&
            child.stopped_token == stopped.stopped_token &&
            !child.returned && !stopped.returned,
        "reset CALL pushes return address, child saves EBX/EBP and faults before its first actor write"
    );
}

class Random final : public openswd3::battle::LegacyBattleBoundedRandomPort {
public:
    u32 calls{};
    u32 last_bound{};

    [[nodiscard]] u32 random_bounded(const u32 bound) override {
        ++calls;
        last_bound = bound;
        return 7U;
    }
};

class UpdatePort final
    : public openswd3::battle::LegacyBattleActorFrameUpdatePort {
public:
    openswd3::battle::LegacyBattleActorFrameUpdateReply reply{
        .returned = true,
        .eax = 0U,
        .ecx = 0xABCDU,
        .edx = 0x9876U,
    };
    openswd3::battle::LegacyBattleActorFrameUpdateReply frame_reply{
        .returned = true,
        .eax = 0x00701000U,
        .ecx = 0xBEEFU,
        .edx = 0x9876U,
        .flags = {.zero = true},
        .flags_known = true,
    };
    u32 calls{};
    u32 last_token{};
    u32 frame_calls{};
    u32 last_action_value{};
    u32 last_argument_zero{};

    [[nodiscard]] openswd3::battle::LegacyBattleActorFrameUpdateReply update(
        openswd3::asset_runtime::LegacyActionRecord& record,
        const u32 record_token,
        const u32 entry_eax,
        const u32 entry_ecx,
        const u32 entry_edx
    ) override {
        ++calls;
        last_token = record_token;
        static_cast<void>(entry_eax);
        static_cast<void>(entry_ecx);
        static_cast<void>(entry_edx);
        record.field_24 = 0x5AU;
        return reply;
    }

    [[nodiscard]] openswd3::battle::LegacyBattleActorFrameUpdateReply
    lookup_frame(
        const u32 action_value,
        const u32 argument_zero,
        const u32 entry_eax,
        const u32 entry_ecx,
        const u32 entry_edx
    ) override {
        ++frame_calls;
        last_action_value = action_value;
        last_argument_zero = argument_zero;
        static_cast<void>(entry_eax);
        static_cast<void>(entry_ecx);
        static_cast<void>(entry_edx);
        return frame_reply;
    }
};

