class ReleasePort final
    : public openswd3::battle::LegacyBattleActorFrameReleasePort {
public:
    openswd3::battle::LegacyBattleActorFrameUpdateReply reply{
        .returned = true,
        .eax = 0xF00DF00DU,
        .ecx = 0xCAFEBABEU,
        .edx = 0xABCD1234U,
    };
    u32 calls{};
    u32 token{};
    u32 entry_eax{};
    std::array<u32, 4U> released_tokens{};
    std::span<openswd3::battle::LegacyBattleActorFrameLinkedNode>
        linked_nodes_to_mutate{};
    u32 next_after_first{};

    [[nodiscard]] openswd3::battle::LegacyBattleActorFrameUpdateReply
    release_emitter(
        const u32 emitter_token,
        const u32 eax,
        const u32 ecx,
        const u32 edx,
        const openswd3::battle::LegacyBattleActorCoordinateFlags& flags
    ) override {
        released_tokens[calls % released_tokens.size()] = emitter_token;
        ++calls;
        if (calls == 1U && linked_nodes_to_mutate.size() > 1U) {
            linked_nodes_to_mutate[1U].next_token = next_after_first;
        }
        token = emitter_token;
        entry_eax = eax;
        static_cast<void>(ecx);
        static_cast<void>(edx);
        static_cast<void>(flags);
        return reply;
    }
};

class LinkedNodeResolver final
    : public openswd3::battle::LegacyBattleActorFrameLinkedNodeResolverPort {
public:
    std::span<const openswd3::battle::LegacyBattleActorFrameLinkedNode> nodes{};
    u32 calls{};
    std::array<u32, 4U> requested_tokens{};

    [[nodiscard]] std::span<
        const openswd3::battle::LegacyBattleActorFrameLinkedNode>
    resolve_linked_nodes(const u32 current_token) override {
        requested_tokens[calls % requested_tokens.size()] = current_token;
        ++calls;
        return nodes;
    }
};

