                        large_frame.frame_owner.reset();
                        tsw_runtime.clear_cache();
                        test.expect_true(
                            tsw_runtime.cache_entry_count() == 0U &&
                                large_prefix.frame_lookup_child.decoder_source
                                        .frame_owner != nullptr &&
                                !large_frame.frame.primary_stream.empty(),
                            "real actor frame lease survives cache clear"
                        );

                        DecodePort opaque_decoder;
                        opaque_decoder.reply.returned = false;
                        mutable_request_counter = 0x00760000U;
                        mutable_heap_size = 0xFFFFFFFEU;
                        mutable_live_size = 0xFFFFFFFDU;
                        mutable_peak_size = 8U;
                        empty_heap_tail = 0U;
                        nonempty_heap_tail = 0x00806000U;
                        writable_heap_head = 0xABCDEF01U;
                        old_tail_backing.fill(0xA5U);
